import { MakeLogicType, afterMount, connect, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { tracingAlertsEventsList } from 'products/tracing/frontend/generated/api'
import { TracingAlertEventApi } from 'products/tracing/frontend/generated/api.schemas'

export interface TracingAlertEventHistoryLogicProps {
    alertId: string
}

export interface EventsPage {
    results: TracingAlertEventApi[]
    next: string | null
    count: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracingAlertEventHistoryLogicValues {
    currentTeamId: number | null // teamLogic
    eventsPage: EventsPage
    eventsPageLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracingAlertEventHistoryLogicActions {
    loadEvents: () => any
    loadMore: () => { value: true }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracingAlertEventHistoryLogicMeta {
    key: string
}

export type tracingAlertEventHistoryLogicType = MakeLogicType<
    tracingAlertEventHistoryLogicValues,
    tracingAlertEventHistoryLogicActions,
    TracingAlertEventHistoryLogicProps,
    tracingAlertEventHistoryLogicMeta
>

export const tracingAlertEventHistoryLogic = kea<tracingAlertEventHistoryLogicType>([
    path((key) => ['products', 'tracing', 'frontend', 'alerting', 'tracingAlertEventHistoryLogic', key]),
    props({} as TracingAlertEventHistoryLogicProps),
    key((props) => props.alertId),

    connect({
        values: [teamLogic, ['currentTeamId']],
    }),

    loaders(({ props, values }) => ({
        eventsPage: [
            { results: [], next: null, count: 0 } as EventsPage,
            {
                loadEvents: async () => {
                    const projectId = String(values.currentTeamId)
                    const response = await tracingAlertsEventsList(projectId, props.alertId)
                    return {
                        results: response.results ?? [],
                        next: response.next ?? null,
                        count: response.count ?? 0,
                    }
                },
                loadMore: async () => {
                    const nextUrl = values.eventsPage.next
                    if (!nextUrl) {
                        return values.eventsPage
                    }
                    const res = await fetch(nextUrl, { credentials: 'include' })
                    if (!res.ok) {
                        throw new Error(`Failed to load more events: ${res.status} ${res.statusText}`)
                    }
                    const data = (await res.json()) as Partial<EventsPage>
                    return {
                        results: [...values.eventsPage.results, ...(data.results ?? [])],
                        next: data.next ?? null,
                        count: data.count ?? values.eventsPage.count,
                    }
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadEvents()
    }),
])
